head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useHeaderContextMenu]<br/>Header 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시 Header 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시해야 합니다.",
        "미설정 또는 false 설정 시 Header 영역에서 마우스 우클릭 시 WebSquare 컨텍스트 메뉴를 표시하지 않아야 합니다. (기본값 false)",
        "contextMenu 속성값에 관계없이 동작해야 합니다.",
        "WebSquare 컨텍스트 메뉴는 기본 12 개 항목을 제공하며 GridView 의 현재 상태에 맞는 메뉴만 표시되어야 합니다.",
        "컨텍스트 메뉴창엔 'w2grid_contextMenu' CSS 클래스가 설정되어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    //  - con_useHeaderContextMenu / con_contextMenu 가 미설정('') 이면
    //    createCList 가 빈 문자열 value 를 자동 제외하므로 properties 키 자체가 빠짐 (기본값 동작)
    let properties = {
        dataList: "data:dlt_bind",
        useHeaderContextMenu: con_useHeaderContextMenu.getValue(),
        contextMenu: con_contextMenu.getValue(),
    };

    let cList = $c.gcm.createCList(properties);

    // oncontextopen / oncontextclick 이벤트 핸들러 부착
    let eList = $c.gcm.createEList(["oncontextopen", "oncontextclick"]);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncontextopen : 컨텍스트 메뉴가 표시될 때 발생
//  - 인자 : rowIndex(헤더는 -1), columnIndex, focusedCellInfo, info(헤더 정보)
//  - info 객체는 속성 개별 출력 (info.isHeader, info.headerId)
scwin.target1_oncontextopen = function (rowIndex, columnIndex, focusedCellInfo, info) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen rowIndex : " + rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen columnIndex : " + columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen info.isHeader : " + info.isHeader);
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextopen info.headerId : " + info.headerId);

    // 컨텍스트 메뉴는 oncontextopen 이후 생성되므로 setTimeout 으로 생성 후 DOM 검증
    //  - 클래스(.w2grid_contextMenu)로 찾으면 순환 검증이 되므로 list 컴포넌트 id(_contextMenu_list)로 탐색한 뒤 클래스 설정 여부를 검증
    setTimeout(function () {
        let menu = document.querySelector("[id$='_contextMenu_list']");
        if (!menu) {
            wf_body_bottom.getObj("scwin").setReturnValue("컨텍스트 메뉴 미생성");
            return;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("'w2grid_contextMenu' 클래스 설정 여부 : " + menu.classList.contains("w2grid_contextMenu"));
        let rows = menu.querySelectorAll(".w2grid_contextMenu_row");
        wf_body_bottom.getObj("scwin").setReturnValue("표시된 메뉴 항목 수 : " + rows.length);
    }, 0);
};



// oncontextclick : context menu 항목 클릭 시 발생
scwin.target1_oncontextclick = function (rowIndex, columnIndex, userMenuId, systemMenu, systemMenuId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextclick systemMenu : " + systemMenu);
    wf_body_bottom.getObj("scwin").setReturnValue("oncontextclick systemMenuId : " + systemMenuId);
};
